import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdminFProf = ({ onClose, onSave }) => {
  const [professor, setProfessor] = useState({
    nome: "Paulo Carvalho",
    email: "paulocv@gmail.com",
    morada: "Rua Artur Mirandela 78, c",
    contacto: "971118277",
    cursos: ["Contabilidade II", "Inglês I"],
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfessor((prevProfessor) => ({
      ...prevProfessor,
      [name]: value,
    }));
  };

  const handleCursoChange = (index, value) => {
    const novosCursos = [...professor.cursos];
    novosCursos[index] = value;
    setProfessor((prevProfessor) => ({
      ...prevProfessor,
      cursos: novosCursos,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSave(professor);
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary">EducaWeb</h1>
      <ul className="nav nav-tabs mt-3">
        <li className="nav-item">
          <a className="nav-link" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="mt-3">
        <h3>Informação do Professor</h3>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Nome</label>
            <input
              type="text"
              name="nome"
              className="form-control"
              value={professor.nome}
              onChange={handleChange}
              required
            />
          </div>
          <div className="form-group">
            <label>Email</label>
            <input
              type="email"
              name="email"
              className="form-control"
              value={professor.email}
              onChange={handleChange}
              required
            />
          </div>
          <div className="form-group">
            <label>Morada</label>
            <input
              type="text"
              name="morada"
              className="form-control"
              value={professor.morada}
              onChange={handleChange}
              required
            />
          </div>
          <div className="form-group">
            <label>Contacto</label>
            <input
              type="text"
              name="contacto"
              className="form-control"
              value={professor.contacto}
              onChange={handleChange}
              required
            />
          </div>
          <div className="form-group">
            <label>Curso que Leciona</label>
            {professor.cursos.map((curso, index) => (
              <input
                key={index}
                type="text"
                className="form-control mb-2"
                value={curso}
                onChange={(e) => handleCursoChange(index, e.target.value)}
                required
              />
            ))}
          </div>
          <div className="d-flex justify-content-between">
            <button type="button" className="btn btn-danger" onClick={onClose}>
              cancelar
            </button>
            <button type="submit" className="btn btn-primary">
              salvar
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AdminFProf;
